const fig=o=>{const id='v3f'+(++FID);REG[id]=o.chart;return `<figure class="v3fig ${o.style||''}" style="margin-inline:0"><h3>${L(o.title[0],o.title[1])}</h3>${o.sub?`<p class="sub">${L(o.sub[0],o.sub[1])}</p>`:''}<div class="v3c" data-id="${id}"></div><div class="src"><span>${L(o.src[0],o.src[1])}</span>${o.note?`<span>${L(o.note[0],o.note[1])}</span>`:''}</div></figure>`};
const story=o=>{const id='v3f'+(++FID);REG[id]=Object.assign({},o.chart,{upto:0});return `<div class="v3story" data-sid="${id}"><div class="stk"><figure class="v3fig ${o.style||''}" style="margin-inline:0"><h3>${L(o.title[0],o.title[1])}</h3>${o.sub?`<p class="sub">${L(o.sub[0],o.sub[1])}</p>`:''}<div class="v3c" data-id="${id}"></div><div class="src"><span>${L(o.src[0],o.src[1])}</span></div></figure></div><div class="steps">${o.steps.map((s,i)=>`<div class="step" data-i="${i}"><div>${L(s[0],s[1])}</div></div>`).join('')}</div></div>`};

