const optSwitch=(note)=>{const lean=window.MODEL&&MODEL.isLean&&MODEL.isLean();return `<div class="v3optbar"><div class="v3opt" role="group" aria-label="Funding option"><button type="button" data-opt="flag" class="${lean?'':'on'}" aria-pressed="${!lean}">${L('Flagship','Duka kuu')}<b>TSh 340M</b></button><button type="button" data-opt="lean" class="${lean?'on':''}" aria-pressed="${!!lean}">${L('Start small','Anza kidogo')}<b>TSh 150M</b></button></div>${note===false?'':`<span>${L('The summary, the cover and the sections marked with this switch follow the option selected here.','Muhtasari, jalada na sehemu zenye kibadilishi hiki zinafuata chaguo lililochaguliwa hapa.')}</span>`}</div>`};
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-opt]');if(!b||!window.MODEL||!MODEL.setOpt)return;const o=b.dataset.opt;if((MODEL.isLean()?'lean':'flag')===o)return;MODEL.setOpt(o);const y=scrollY;try{if(typeof route==='function')route();else location.reload()}catch(err){location.reload()}scrollTo(0,y);paintOpt()});
function paintOpt(){const lean=window.MODEL&&MODEL.isLean&&MODEL.isLean();document.querySelectorAll('.v3opt [data-opt]').forEach(b=>{const on=(b.dataset.opt==='lean')===!!lean;b.classList.toggle('on',on);b.setAttribute('aria-pressed',on)});
 try{const I=MODEL.cur.inputs,amt=Math.round(I.seed.amount/1e6),st=document.querySelector('.op-stats b');if(st){st.dataset.n=amt;st.dataset.p='TSh ';st.textContent='TSh '+amt+'M';const sp=st.nextElementSibling;if(sp)sp.textContent=lean?'seed ask · start small':'seed ask · flagship'}
  const mb=document.querySelector('.op-meta.b span b');if(mb)mb.textContent='TSh '+amt+'M'+(lean?' · start small':' · flagship')}catch(e){}}
const LN={
 's3-1':['This section shows the flagship store design: 180 m² on a prime street. In the start-small option selected, the store uses the same six Care Zones in about 100 m² on a good secondary street, open 09:00–20:00, with a manual check corner instead of the Afya Check kiosk.','Sehemu hii inaonyesha muundo wa duka kuu: m² 180 katika barabara kuu. Katika chaguo la kuanza kidogo lililochaguliwa, duka linatumia Maeneo sita yaleyale ya Huduma katika takriban m² 100 kwenye barabara nzuri ya pili, likifunguliwa saa 3:00 asubuhi hadi saa 2:00 usiku, na kona ya kupima ya kawaida badala ya kibanda cha Afya Check.'],
 's3-3':['This section shows the flagship’s Afya Check kiosk. In the start-small option selected, the same free check is done at a manual check corner by an adviser, with about 35 checks a day by month 12.','Sehemu hii inaonyesha kibanda cha Afya Check cha duka kuu. Katika chaguo la kuanza kidogo lililochaguliwa, kipimo hichohicho cha bure kinafanywa kwenye kona ya kupima na mshauri, takriban vipimo 35 kwa siku ifikapo mwezi 12.'],
 's3-4':['Figures in this section are for the flagship. In the start-small option selected, the store reaches about '+(()=>{try{return Math.round(MODEL.small.get('base').months[11].members)}catch(e){return 389}})()+' box members by month 12; the cards, packages, prices and monthly cycle are the same.','Takwimu katika sehemu hii ni za duka kuu. Katika chaguo la kuanza kidogo lililochaguliwa, duka linafikia takriban wanachama '+(()=>{try{return Math.round(MODEL.small.get('base').months[11].members)}catch(e){return 389}})()+' wa box ifikapo mwezi 12; kadi, vifurushi, bei na mzunguko wa kila mwezi ni vilevile.'],
 's3-6':['The store plan and shelf counts in this section are for the flagship. In the start-small option selected, the 100 m² store carries the core 300 product families on fewer bays; slower lines are ordered for delivery.','Ramani ya duka na idadi ya rafu katika sehemu hii ni za duka kuu. Katika chaguo la kuanza kidogo lililochaguliwa, duka la m² 100 linabeba familia kuu 300 za bidhaa kwenye rafu chache; bidhaa zinazouzwa polepole zinaagizwa kwa usafirishaji.'],
 's5-4':['The twelve-year plan is modelled with the flagship as store 1. In the start-small option selected, store 1 is the 100 m² store funded by the TSh 150M seed; from store 2 onwards the plan, the gates and the capital needed are the same.','Mpango wa miaka kumi na miwili umepangwa duka kuu likiwa duka la 1. Katika chaguo la kuanza kidogo lililochaguliwa, duka la 1 ni duka la m² 100 linalogharamiwa na mtaji wa awali wa TSh 150M; kuanzia duka la 2 mpango, vizingiti na mtaji unaohitajika ni vilevile.'],
 's4-3':['This section shows the flagship’s salaried riders. In the start-small option selected, deliveries are made by partner riders paid per order, about TSh 3,000 a delivery, and own riders are added later from the store’s own cash.','Sehemu hii inaonyesha wasafirishaji wa mshahara wa duka kuu. Katika chaguo la kuanza kidogo lililochaguliwa, usafirishaji unafanywa na wasafirishaji washirika wanaolipwa kwa kila oda, takriban TSh 3,000 kwa safari, na wasafirishaji wa duka wanaongezwa baadaye kwa fedha za duka lenyewe.'],
 's4-4':['This section describes the flagship team of eight on two shifts. In the start-small option selected, the store runs one long shift, 09:00–20:00, with five people: a store lead, three health advisers and a picker and packer, and partner riders paid per order.','Sehemu hii inaeleza timu ya duka kuu ya watu wanane kwa zamu mbili. Katika chaguo la kuanza kidogo lililochaguliwa, duka linaendeshwa kwa zamu moja ndefu, saa 3:00 asubuhi hadi saa 2:00 usiku, na watu watano: kiongozi wa duka, washauri watatu wa afya na mfungashaji, pamoja na wasafirishaji washirika wanaolipwa kwa kila oda.']};
