;
/* brief5 · v3 analyst briefs for 4.5 Quality, Part 5 (Growth) and 7.1, 7.2, 7.4, 7.5. Numbers that depend on the funding option follow MODEL.cur. */
(function(){
'use strict';
const V=window.V3;if(!V)return;const {L,P,lede,sh,imp,calc,fig,kpis}=V;
window.V3MODS=window.V3MODS||{};
const nf=n=>Math.round(n).toLocaleString('en'),tm0=n=>'TSh '+Math.round(n/1e6)+'M',tb=n=>'TSh '+(n/1e9).toFixed(2)+'B',tbS=n=>'TSh bilioni '+(n/1e9).toFixed(2),pc=(n,d)=>(n*100).toFixed(d||0)+'%';
const CUR=()=>{const M=window.MODEL,lean=!!(M.isLean&&M.isLean());return {M,lean,I:M.cur.inputs,B:M.cur.get('base'),opt:lean?['start-small option','chaguo la kuanza kidogo']:['flagship option','chaguo la duka kuu']}};
const optTag=c=>L(`Shown for the ${c.opt[0]} · ${tm0(c.I.seed.amount)} seed`,`Inaonyeshwa kwa ${c.opt[1]} · mtaji wa awali ${tm0(c.I.seed.amount)}`);

/* ================= 4.5 QUALITY & COMPLIANCE ================= */
window.V3MODS['s4-5']=()=>[[['In short · quality as the product','Uchambuzi · ubora ndiyo bidhaa'],`<div class="v3b">
  ${lede('In a market where about one medical product in ten is substandard or falsified, the ability to prove that every pack is genuine, registered and in date is not an overhead. It is the main reason a household changes where it buys. Afya Basics is designed so that this proof is produced by the system, every day, for every pack.','Katika soko ambalo takriban bidhaa moja ya tiba kati ya kumi ni duni au bandia, uwezo wa kuthibitisha kwamba kila pakiti ni halisi, imesajiliwa na haijaisha muda wake si gharama ya ziada. Ndiyo sababu kuu kaya inabadilisha mahali inaponunua. Afya Basics imeundwa ili uthibitisho huu utolewe na mfumo, kila siku, kwa kila pakiti.')}
  ${kpis([['0','medicines sold by Afya: a licensed partner pharmacy sells them','dawa zinazouzwa na Afya: famasia mshirika yenye leseni inaziuza',1],['5','checks on every pack before it reaches a shelf','ukaguzi kwa kila pakiti kabla ya kufika rafuni'],['30','days before expiry, a batch leaves the shelf automatically','siku kabla ya muda kuisha, kundi linaondolewa rafuni moja kwa moja'],['TSh 6M','a year for insurance and licences in the model','kwa mwaka kwa bima na leseni katika modeli']])}
  ${sh('The decision that shapes everything else','Uamuzi unaoathiri kila kitu kingine')}
  ${P('Tanzania’s Pharmacy Act allows medicines to be sold only from premises registered with the Pharmacy Council and run by a registered pharmacist, and it makes no general exception for over-the-counter medicines such as paracetamol or oral rehydration salts. Afya Basics therefore sells no medicine at all. It sells devices, diagnostics, first-aid supplies, hygiene, mother-and-baby products, mobility aids and cosmetics, which fall under TMDA, TBS and the data-protection regulator. Medicines reach members through a licensed partner pharmacy, on that pharmacy’s receipt, in a sealed bag that travels with the box. The result is a store that needs no pharmacist salary, carries no medicine stock and cannot be closed for a dispensing breach, while members still receive everything their month requires.','Sheria ya Famasi ya Tanzania inaruhusu dawa kuuzwa tu kutoka majengo yaliyosajiliwa na Baraza la Famasi na yanayoendeshwa na mfamasia aliyesajiliwa, na haina msamaha wa jumla kwa dawa zinazouzwa bila agizo kama paracetamol au ORS. Kwa hiyo Afya Basics haiuzi dawa yoyote. Inauza vifaa, vipimo, vifaa vya huduma ya kwanza, usafi, bidhaa za mama na mtoto, vifaa vya uhamaji na vipodozi, ambavyo viko chini ya TMDA, TBS na mdhibiti wa ulinzi wa taarifa. Dawa zinawafikia wanachama kupitia famasia mshirika yenye leseni, kwa risiti ya famasia hiyo, kwenye mfuko uliofungwa unaosafiri pamoja na boksi. Matokeo yake ni duka lisilohitaji mshahara wa mfamasia, lisilobeba akiba ya dawa na lisiloweza kufungwa kwa kosa la utoaji dawa, huku wanachama bado wakipata kila wanachohitaji kwa mwezi.')}
  </div>
  ${fig({title:['Each safeguard has a clock','Kila kinga ina muda wake'],sub:['Maximum time for each quality action, days','Muda wa juu kwa kila hatua ya ubora, siku'],src:['Source: section 4.5 quality procedures; TMDA device registration guidance','Chanzo: taratibu za ubora sehemu 4.5; mwongozo wa usajili wa vifaa wa TMDA'],note:['Registration time is why Afya launches only with brands already registered by their distributors','Muda wa usajili ndiyo sababu Afya inaanza tu na chapa ambazo tayari zimesajiliwa na wasambazaji wake'],
   chart:{type:'hbars',max:240,ticks:[0,60,120,180,240],rows:[[['Recall: customers told, same day','Kurejesha: wateja wanaarifiwa'],1,'1','gold'],[['Faulty device swapped','Kifaa kibovu kinabadilishwa'],7,'7','grn'],[['Batch off shelf before expiry','Kundi linaondolewa kabla ya kuisha'],30,'30','grn'],[['TMDA registration, new import','Usajili TMDA, kifaa kipya'],240,'240','grn2']]}})}
  <div class="v3b">
  ${calc({t:['Worked example · what compliance costs a year','Mfano wa hesabu · uzingatiaji unagharimu kiasi gani kwa mwaka'],
   rows:[['TMDA dealer’s permit for medical devices, retail','Kibali cha TMDA cha muuzaji wa vifaa tiba, rejareja','TSh 60,000'],['Data-protection registration, TSh 100,000 over five years','Usajili wa ulinzi wa taarifa, TSh 100,000 kwa miaka mitano','TSh 20,000'],['Published fees a year','Ada zilizochapishwa kwa mwaka','TSh 80,000'],['Model budget for insurance and licences','Bajeti ya modeli kwa bima na leseni','TSh 6,000,000',1]],
   n:['The remainder covers insurance and the fees set at inspection (OSHA, fire, business licence). Product registration costs Afya nothing at launch because distributors hold the registrations and pay the yearly retention fees.','Kiasi kilichobaki kinagharamia bima na ada zinazopangwa wakati wa ukaguzi (OSHA, zimamoto, leseni ya biashara). Usajili wa bidhaa hauigharimu Afya chochote mwanzoni kwa sababu wasambazaji ndio wanaoshikilia usajili na kulipa ada za kila mwaka.']})}
  ${imp('For an investor, the compliance design removes the two risks that close health retailers most often: selling medicines without the right licence, and selling a product that cannot be traced. Both are designed out rather than managed. What remains is a published, low fee base and a quality record that the store can show to any customer, clinic or regulator on request.','Kwa mwekezaji, muundo wa uzingatiaji unaondoa hatari mbili zinazofunga maduka ya afya mara nyingi zaidi: kuuza dawa bila leseni sahihi, na kuuza bidhaa isiyoweza kufuatiliwa. Zote mbili zimeondolewa kwa muundo badala ya kusimamiwa. Kinachobaki ni ada ndogo zilizochapishwa na rekodi ya ubora ambayo duka linaweza kumwonyesha mteja, kliniki au mdhibiti yeyote akiomba.')}
  </div>`]];

/* ================= 5.1 MARKETING & ACQUISITION ================= */
window.V3MODS['s5-1']=()=>{const c=CUR(),I=c.I,B=c.B,mb=I.members,m=B.months;
 const launch=((I.seed.use||[]).find(u=>/marketing/i.test(u[0]))||[0,0])[1],mkt=I.opex_month.marketing*12+launch,joins=m.reduce((t,x)=>t+x.joins,0),cac=mkt/joins;
 const NF=window.MODEL.NETF||1/1.153,prod=(mb.avg_box-mb.packing_delivery_in_price)*NF,gpm=prod*mb.box_products_gm-(prod+mb.packing_delivery_in_price)*I.tax.payment_fees,life=1/mb.monthly_churn,ltv=gpm*life,pay=cac/gpm,mem=Math.round(m[11].members);
 return [[['In short · what a member costs, and what a member returns','Uchambuzi · mwanachama anagharimu kiasi gani, na analeta kiasi gani'],`<div class="v3b">
  ${V.optSwitch()}
  ${lede('Afya Basics does not buy customers with discounts. The store itself is the advertisement, the free Afya Check at the door is the reason to walk in, and the monthly box is the reason to stay. The marketing budget is therefore small, and the test an investor should apply is simple: how much it costs to win one member, and how quickly that member pays it back.','Afya Basics hainunui wateja kwa punguzo. Duka lenyewe ndilo tangazo, Afya Check ya bure mlangoni ndiyo sababu ya kuingia, na boksi la kila mwezi ndilo sababu ya kubaki. Kwa hiyo bajeti ya masoko ni ndogo, na kipimo ambacho mwekezaji anapaswa kutumia ni rahisi: inagharimu kiasi gani kumpata mwanachama mmoja, na mwanachama huyo analipa gharama hiyo kwa haraka kiasi gani.')}
  ${kpis([[`TSh ${nf(cac)}`,'marketing spent to win one member in year 1','gharama ya masoko kumpata mwanachama mmoja mwaka wa 1'],[pay.toFixed(1),'months to earn that cost back','miezi ya kurudisha gharama hiyo'],[`${(ltv/cac).toFixed(1)}×`,'lifetime gross profit against the cost to win','faida ghafi ya maisha dhidi ya gharama ya kumpata',1],[nf(mem),'Afya Box members by month 12','wanachama wa Afya Box ifikapo mwezi 12']])}
  </div>
  ${fig({title:['A member repays the cost of winning them within a quarter','Mwanachama analipa gharama ya kumpata ndani ya robo mwaka'],sub:['Cost to win one member against the gross profit that member brings, TSh','Gharama ya kumpata mwanachama mmoja dhidi ya faida ghafi anayoleta, TSh'],src:['Source: master model, marketing budget, member joins and box margin','Chanzo: modeli kuu, bajeti ya masoko, wanachama wanaojiunga na faida ya boksi'],note:[optTag(c),optTag(c)],
   chart:{type:'hbars',max:Math.ceil(ltv/50000)*50000,ticks:[0,50000,100000,150000,200000].filter(x=>x<=Math.ceil(ltv/50000)*50000),rows:[[['Cost to win one member','Gharama ya kumpata mwanachama'],cac,nf(cac),'gold'],[['Gross profit after 3 months','Faida ghafi baada ya miezi 3'],gpm*3,nf(gpm*3),'grn2'],[['Gross profit after 6 months','Faida ghafi baada ya miezi 6'],gpm*6,nf(gpm*6),'grn2'],[[`Lifetime, ${life.toFixed(1)} months on average`,`Maisha yote, wastani wa miezi ${life.toFixed(1)}`],ltv,nf(ltv),'grn']]}})}
  <div class="v3b">
  ${calc({t:['Worked example · the payback, step by step','Mfano wa hesabu · kurudisha gharama, hatua kwa hatua'],
   rows:[['Marketing in year 1, including the launch','Masoko mwaka wa 1, pamoja na uzinduzi',tm0(mkt)],['÷ members who joined in year 1','÷ wanachama waliojiunga mwaka wa 1',nf(joins)],['Cost to win one member','Gharama ya kumpata mwanachama mmoja','TSh '+nf(cac)],['Gross profit a member brings a month','Faida ghafi ya mwanachama kwa mwezi','TSh '+nf(gpm)],[`× ${life.toFixed(1)} months average membership (1 ÷ ${pc(mb.monthly_churn)} leaving a month)`,`× wastani wa miezi ${life.toFixed(1)} ya uanachama (1 ÷ ${pc(mb.monthly_churn)} wanaoondoka kwa mwezi)`,'TSh '+nf(ltv),1]],
   n:['Conservative by design: the whole marketing budget is charged to members, although it also brings every walk-in customer and online order, and the 26% box margin is below the store margin. A ratio above three is generally read as healthy.','Ni ya tahadhari kwa makusudi: bajeti yote ya masoko inabebeshwa wanachama, ingawa pia inaleta kila mteja anayeingia dukani na kila oda ya mtandaoni, na faida ya boksi ya 26% iko chini ya faida ya duka. Uwiano unaozidi tatu kwa kawaida unachukuliwa kuwa mzuri.']})}
  ${imp(`The single number most worth watching after launch is the share of members who leave each month. At ${pc(mb.monthly_churn)} an average member stays ${life.toFixed(1)} months; at 6% the same member stays about 16.7 months and is worth a third more, with no extra marketing. Retention, not advertising, is where the value of this business is made.`,`Namba moja inayostahili kufuatiliwa zaidi baada ya uzinduzi ni sehemu ya wanachama wanaoondoka kila mwezi. Kwa ${pc(mb.monthly_churn)} mwanachama wa wastani anabaki miezi ${life.toFixed(1)}; kwa 6% mwanachama huyohuyo anabaki takriban miezi 16.7 na thamani yake inaongezeka kwa theluthi moja, bila masoko ya ziada. Kuwabakiza wanachama, si matangazo, ndiko thamani ya biashara hii inakotengenezwa.`)}
  </div>`]];};

/* ================= 5.2 PARTNERSHIPS & B2B ================= */
window.V3MODS['s5-2']=()=>{const c=CUR(),Y=c.B.years,sh2=c.I.growth.b2b_share,b2b=y=>y.revenue*sh2/(1+sh2);
 const ys=Y.filter(y=>y.year>1),y5=Y[4],y12=Y[11];
 return [[['In short · one agreement, many households','Uchambuzi · makubaliano moja, kaya nyingi'],`<div class="v3b">
  ${lede('A clinic, an employer, a school, a hotel, an insurer or a diaspora association each serves many households at once. One signed agreement can bring dozens of families without another shilling of advertising. The plan treats this channel cautiously: nothing is counted in year 1, and from year 2 business sales are modelled at a modest share on top of household sales.','Kliniki, mwajiri, shule, hoteli, kampuni ya bima au chama cha wanadiaspora kila kimoja kinahudumia kaya nyingi kwa wakati mmoja. Makubaliano moja yaliyosainiwa yanaweza kuleta familia nyingi bila shilingi nyingine ya matangazo. Mpango unashughulikia njia hii kwa tahadhari: hakuna kinachohesabiwa mwaka wa 1, na kuanzia mwaka wa 2 mauzo ya biashara yanapangwa kwa sehemu ndogo juu ya mauzo ya kaya.')}
  ${kpis([['0','business sales counted in year 1','mauzo ya biashara yanayohesabiwa mwaka wa 1',1],[pc(sh2,1),'on top of store sales from year 2','juu ya mauzo ya duka kuanzia mwaka wa 2'],[tb(b2b(y5)),'business sales in year 5, base case','mauzo ya biashara mwaka wa 5, hali ya msingi'],[tb(b2b(y12)),'business sales in year 12, base case','mauzo ya biashara mwaka wa 12, hali ya msingi']])}
  </div>
  ${fig({title:['Business sales grow with the network, not ahead of it','Mauzo ya biashara yanakua pamoja na mtandao, si kabla yake'],sub:['Business-to-business revenue by year, base case, TSh billion','Mapato ya biashara kwa biashara kwa mwaka, hali ya msingi, TSh bilioni'],src:['Source: master model, twelve-year table × business share','Chanzo: modeli kuu, jedwali la miaka kumi na miwili × sehemu ya biashara'],note:['Every partner is a target; no agreement is signed today','Kila mshirika ni lengo; hakuna makubaliano yaliyosainiwa leo'],
   chart:{type:'cols',max:Math.ceil(b2b(y12)/1e9),ticks:Array.from({length:Math.ceil(b2b(y12)/1e9)+1},(_,i)=>i),bars:ys.map(y=>[[`Y${y.year}`,`M${y.year}`],+(b2b(y)/1e9).toFixed(2),(b2b(y)/1e9).toFixed(1),y.year===5?'gold':'grn2'])}})}
  <div class="v3b">
  ${calc({t:['Worked example · year 5 in boxes','Mfano wa hesabu · mwaka wa 5 kwa maboksi'],
   rows:[[`Total revenue in year 5 (${y5.stores} stores)`,`Mapato yote mwaka wa 5 (maduka ${y5.stores})`,tb(y5.revenue)],[`× ${pc(sh2)} ÷ ${(1+sh2).toFixed(2)} (business share already inside the total)`,`× ${pc(sh2)} ÷ ${(1+sh2).toFixed(2)} (sehemu ya biashara tayari iko ndani ya jumla)`,tb(b2b(y5))],['Boxes a month: ÷ 12 months ÷ TSh 80,500 average box','Maboksi kwa mwezi: ÷ miezi 12 ÷ boksi la wastani TSh 80,500',nf(b2b(y5)/12/80500)],['Boxes a month per store','Maboksi kwa mwezi kwa kila duka',nf(b2b(y5)/12/80500/y5.stores),1]],
   n:['One employer with 80 staff on Afya Kazini, or one maternity ward referring new mothers, would supply much of one store’s share. No partner may exceed about one fifth of business revenue, and partners pay the same published prices as households.','Mwajiri mmoja mwenye wafanyakazi 80 kwenye Afya Kazini, au wodi moja ya wazazi inayowaelekeza mama wapya, angetoa sehemu kubwa ya mgao wa duka moja. Hakuna mshirika anayeruhusiwa kuzidi takriban moja ya tano ya mapato ya biashara, na washirika wanalipa bei zilezile zilizochapishwa kama kaya.']})}
  ${imp('Two changes make partners more valuable now. The Universal Health Insurance Act requires every employer to ensure its staff are insured, and the national scheme started in January 2026. Employers and insurers now have a direct interest in keeping people healthy at lower cost, which is what a monthly box, a free check and a first-aid service provide. The model counts none of that upside in year 1.','Mabadiliko mawili yanawafanya washirika kuwa na thamani zaidi sasa. Sheria ya Bima ya Afya kwa Wote inamtaka kila mwajiri kuhakikisha wafanyakazi wake wana bima, na mpango wa kitaifa ulianza Januari 2026. Waajiri na kampuni za bima sasa wana maslahi ya moja kwa moja katika kuwaweka watu na afya njema kwa gharama ndogo, ambayo ndiyo boksi la mwezi, kipimo cha bure na huduma ya kwanza vinavyotoa. Modeli haihesabu faida hiyo yoyote mwaka wa 1.')}
  </div>`]];};

/* ================= 5.3 COMPETITION ================= */
window.V3MODS['s5-3']=()=>[[['In short · the position nobody holds','Uchambuzi · nafasi ambayo hakuna anayeishikilia'],`<div class="v3b">
  ${lede('Tanzanian households already buy health products from more than 17,400 accredited drug shops, from pharmacies, supermarkets, street sellers, apps and hospital pharmacies. Each serves one need well. None plans the household’s health month by month. Afya Basics does not try to be the cheapest counter or the largest aisle; it competes on four things together that no outlet type offers at once.','Kaya za Tanzania tayari zinanunua bidhaa za afya kutoka maduka ya dawa yaliyoidhinishwa zaidi ya 17,400, kutoka famasi, maduka makubwa, wauzaji wa mitaani, programu na famasi za hospitali. Kila moja linahudumia hitaji moja vizuri. Hakuna linalopanga afya ya kaya mwezi kwa mwezi. Afya Basics haijaribu kuwa kaunta ya bei nafuu zaidi wala rafu kubwa zaidi; inashindana kwa mambo manne kwa pamoja ambayo hakuna aina ya duka inayoyatoa kwa wakati mmoja.')}
  </div>
  ${fig({title:['Strong on one thing each; nobody plans the month','Kila mmoja ana nguvu kwenye jambo moja; hakuna anayepanga mwezi'],sub:['Score out of 35 on seven criteria (speed, trust, price clarity, advice, membership, delivery, diaspora)','Alama kati ya 35 kwa vigezo saba (kasi, uaminifu, uwazi wa bei, ushauri, uanachama, usafirishaji, diaspora)'],src:['Source: section 5.3 comparison matrix, founders’ assessment','Chanzo: jedwali la ulinganisho sehemu 5.3, tathmini ya waanzilishi'],note:['Afya Basics’ score is a target to be proven, not a result; no named company is scored','Alama ya Afya Basics ni lengo la kuthibitishwa, si matokeo; hakuna kampuni iliyotajwa kwa jina'],
   chart:{type:'hbars',max:35,ticks:[0,7,14,21,28,35],rows:[[['Afya Basics (target)','Afya Basics (lengo)'],33,'33','gold'],[['Supermarket health aisles','Rafu za afya za maduka makubwa'],18,'18','grn2'],[['Online marketplaces and apps','Masoko ya mtandaoni na programu'],17,'17','grn2'],[['Hospital pharmacies','Famasi za hospitali'],16,'16','grn2'],[['Traditional pharmacies and ADDOs','Famasi za kawaida na ADDO'],14,'14','grn2'],[['Informal sellers','Wauzaji wasio rasmi'],11,'11','#5b6b64']]}})}
  <div class="v3b">
  ${sh('Why households switch','Kwa nini kaya zinabadilisha')}
  ${P('People rarely change supplier because of an advertisement. They change after a poor experience: the product is out of stock, the strips do not fit the meter, the queue is long, the price changed since last month. Afya Basics is designed around those moments. The top 100 items carry a stock-out target below 2%, four to five registered brands in the same price range give a safe alternative the adviser can explain, and members do not queue at all because the box arrives before supplies run out.','Watu mara chache hubadilisha msambazaji kwa sababu ya tangazo. Wanabadilisha baada ya uzoefu mbaya: bidhaa imeisha, vipande vya kupima havilingani na kifaa, foleni ni ndefu, bei imebadilika tangu mwezi uliopita. Afya Basics imeundwa kuzunguka nyakati hizo. Bidhaa 100 za juu zina lengo la kukosekana chini ya 2%, chapa nne hadi tano zilizosajiliwa za bei moja zinatoa mbadala salama ambao mshauri anaweza kuueleza, na wanachama hawapangi foleni kabisa kwa sababu boksi linafika kabla mahitaji hayajaisha.')}
  ${calc({t:['Worked example · the regional precedent','Mfano wa hesabu · mfano wa kikanda'],
   rows:[['Goodlife Pharmacies stores, November 2016','Maduka ya Goodlife Pharmacies, Novemba 2016','19'],['Stores in Kenya and Uganda, July 2025','Maduka Kenya na Uganda, Julai 2025','148'],['Growth in under nine years','Ukuaji ndani ya chini ya miaka tisa','7.8×'],['Afya Basics plan, stores by year 12, gated at every stage','Mpango wa Afya Basics, maduka ifikapo mwaka 12, kwa vizingiti kila hatua','47',1]],
   n:['The comparison does not prove that Afya Basics will succeed. It shows that East African customers move from small outlets to an organised, trusted chain, and that investors and development-finance lenders finance that move. A pharmacy chain built around medicines is also the most likely entrant; Afya Basics is built around the household’s monthly plan instead.','Ulinganisho huu hauthibitishi kwamba Afya Basics itafanikiwa. Unaonyesha kwamba wateja wa Afrika Mashariki wanahama kutoka maduka madogo kwenda mtandao uliopangwa na unaoaminika, na kwamba wawekezaji na wakopeshaji wa fedha za maendeleo wanafadhili mabadiliko hayo. Mtandao wa famasi uliojengwa kuzunguka dawa pia ndio mshindani anayeweza kuingia zaidi; Afya Basics imejengwa kuzunguka mpango wa kila mwezi wa kaya badala yake.']})}
  ${imp('The defensible part of the model is not the green walls or the blood-pressure machine, which any shop can copy. It is the system underneath: a record of what each household needs next, one platform running till, stock, members and delivery, and a reputation for registered products at one published price. Each of these strengthens with every member and every store.','Sehemu ya modeli inayoweza kulindwa si kuta za kijani wala mashine ya shinikizo la damu, ambavyo duka lolote linaweza kuiga. Ni mfumo ulio chini yake: kumbukumbu ya kile kila kaya inachohitaji baadaye, jukwaa moja linaloendesha malipo, akiba, wanachama na usafirishaji, na sifa ya bidhaa zilizosajiliwa kwa bei moja iliyochapishwa. Kila kimoja kinaimarika kwa kila mwanachama na kila duka.')}
  </div>`]];

/* ================= 5.4 SCALING ================= */
window.V3MODS['s5-4']=()=>{const c=CUR(),G=c.I.growth,Y=c.B.years;
 const m1=G.mature_store_revenue,gp=m1*G.store_gm,prof=gp-G.store_opex_year;
 const st=[[G.ramp[0],'Year 1','Mwaka 1'],[G.ramp[1],'Year 2','Mwaka 2'],[1,'Year 3','Mwaka 3'],[1,'Year 4','Mwaka 4'],[1,'Year 5','Mwaka 5']];let cum=-G.new_store_capex;const cash=st.map(([r,e,s])=>{cum+=m1*r*G.store_gm-G.store_opex_year;return [e,s,cum]});
 return [[['In short · one store, then a chain, on evidence','Uchambuzi · duka moja, kisha mtandao, kwa ushahidi'],`<div class="v3b">
  ${lede(`The plan grows Afya Basics from one store in Dar es Salaam to ${Y[11].stores} stores in twelve years. Three questions decide whether that is credible: does a mature store make money, how much capital does the chain need, and what happens if customers buy less. The answers are below, and each new stage opens only when the stores already open have met written targets.`,`Mpango unakuza Afya Basics kutoka duka moja Dar es Salaam hadi maduka ${Y[11].stores} katika miaka kumi na miwili. Maswali matatu yanaamua kama hilo linaaminika: je, duka lililokomaa linapata faida, mtandao unahitaji mtaji kiasi gani, na nini kinatokea wateja wakinunua kidogo. Majibu yako hapa chini, na kila hatua mpya inafunguliwa tu pale maduka yaliyopo yanapofikia malengo yaliyoandikwa.`)}
  ${kpis([[tm0(G.new_store_capex),'capital to open each new store','mtaji wa kufungua kila duka jipya'],[tm0(prof),'a year from a mature store, before head office','kwa mwaka kutoka duka lililokomaa, kabla ya ofisi kuu'],[pc(prof/G.new_store_capex),'yearly return on the capital, once mature','faida ya mwaka kwa mtaji, likishakomaa',1],['5','the year in which a new store repays its capital and first-year loss','mwaka ambao duka jipya linarudisha mtaji wake na hasara ya mwaka wa kwanza']])}
  </div>
  ${fig({title:['A new store pays for itself during its fifth year','Duka jipya linajilipia katika mwaka wake wa tano'],sub:['Cumulative cash of one new store after its TSh 170M build, TSh million','Fedha za jumla za duka moja jipya baada ya ujenzi wa TSh milioni 170, TSh milioni'],src:['Source: master model, growth inputs (ramp 55% · 85% · 100%, gross margin 26%, running costs TSh 315M)','Chanzo: modeli kuu, vigezo vya ukuaji (ukuaji 55% · 85% · 100%, faida ghafi 26%, gharama za uendeshaji TSh milioni 315)'],note:['Before head office, tax and interest; each store is charged the flagship’s prime rent','Kabla ya ofisi kuu, kodi na riba; kila duka linabebeshwa kodi ya pango ya barabara kuu ya duka kuu'],
   chart:{type:'pn',max:Math.max(50,Math.ceil(Math.max(...cash.map(x=>x[2]/1e6))/50)*50),min:Math.floor(Math.min(...cash.map(x=>x[2]/1e6))/50)*50,ticks:[Math.floor(Math.min(...cash.map(x=>x[2]/1e6))/50)*50,0],tf:t=>t,bars:cash.map(([e,s,v])=>[[e,s],Math.round(v/1e6),nf(v/1e6)])}})}
  <div class="v3b">
  ${sh('The lever that is not in the model','Kigezo ambacho hakimo kwenye modeli')}
  ${P('The model charges every store the flagship’s prime-street rent of TSh 11.9M a month. Most later stores will be neighbourhood stores on secondary streets, where a 180 m² unit at about US$14 per m² would cost about TSh 6.7M a month. That would add about TSh 63M a year to each mature store’s profit. The saving is not counted: it is upside, tested store by store before each lease is signed.','Modeli inabebesha kila duka kodi ya pango ya barabara kuu ya duka kuu ya TSh milioni 11.9 kwa mwezi. Maduka mengi ya baadaye yatakuwa ya mitaa kwenye barabara za pili, ambapo jengo la m² 180 kwa takriban US$14 kwa m² lingegharimu takriban TSh milioni 6.7 kwa mwezi. Hilo lingeongeza takriban TSh milioni 63 kwa mwaka kwenye faida ya kila duka lililokomaa. Akiba hiyo haihesabiwi: ni faida ya ziada, inayojaribiwa duka kwa duka kabla ya kila mkataba wa pango kusainiwa.')}
  ${calc({t:['Worked example · one mature store','Mfano wa hesabu · duka moja lililokomaa'],
   rows:[['Sales a year','Mauzo kwa mwaka',tb(m1)],[`× ${pc(G.store_gm)} gross margin`,`× faida ghafi ${pc(G.store_gm)}`,tm0(gp)],['− running costs, including prime rent','− gharama za uendeshaji, pamoja na kodi ya barabara kuu','− '+tm0(G.store_opex_year)],['Store profit before head office','Faida ya duka kabla ya ofisi kuu',tm0(prof)],[`Yearly return: ÷ ${tm0(G.new_store_capex)} capital`,`Faida ya mwaka: ÷ mtaji wa ${tm0(G.new_store_capex)}`,pc(prof/G.new_store_capex),1]],
   n:['In the downside case (demand 25% lower, costs 5% higher) a mature store loses money, so gate 1 would not open: store 2 is funded only after the first store makes a monthly profit for three months in a row. In that case the capital at risk is the seed, not the twelve-year plan.','Katika hali mbaya (mahitaji chini kwa 25%, gharama juu kwa 5%) duka lililokomaa linapata hasara, hivyo kizingiti cha 1 kisingefunguka: duka la 2 linafadhiliwa tu baada ya duka la kwanza kupata faida ya kila mwezi kwa miezi mitatu mfululizo. Katika hali hiyo mtaji ulio hatarini ni mtaji wa awali, si mpango wa miaka kumi na miwili.']})}
  ${imp('The chain needs about TSh 1.86B of outside capital after the seed in the base case, raised in two later rounds and with development-finance debt, and from year 7 it funds its own openings. Because each stage opens only on evidence, an investor’s capital follows results rather than projections, and a weak first store stops the plan before it consumes growth capital.','Mtandao unahitaji takriban TSh bilioni 1.86 za mtaji wa nje baada ya mtaji wa awali katika hali ya msingi, zitakazotafutwa katika awamu mbili za baadaye na kwa mkopo wa fedha za maendeleo, na kuanzia mwaka wa 7 unajifadhili wenyewe kufungua maduka. Kwa sababu kila hatua inafunguliwa tu kwa ushahidi, mtaji wa mwekezaji unafuata matokeo badala ya makadirio, na duka la kwanza dhaifu linasimamisha mpango kabla haujatumia mtaji wa ukuaji.')}
  </div>`]];};

/* ================= 7.1 SETUP ================= */
window.V3MODS['s7-1']=()=>{const c=CUR(),g=c.I.seed.phase0_gap,gap=g.research_setup_costs-g.phase0_budget;
 return [[['In short · eight months from company to opening day','Uchambuzi · miezi minane kutoka kampuni hadi siku ya ufunguzi'],`<div class="v3b">
  ${V.optSwitch()}
  ${lede('Opening a health store in Tanzania involves six regulators, a lease, a fit-out and a team, and the order matters: the location decides the licences, the licences decide when stock can be bought, and the stock decides the opening date. The plan runs from six months before opening to the first month of trading, and the seed is released in step with it.','Kufungua duka la afya Tanzania kunahusisha wadhibiti sita, mkataba wa pango, ukarabati na timu, na mpangilio ni muhimu: eneo linaamua leseni, leseni zinaamua lini bidhaa zinaweza kununuliwa, na bidhaa zinaamua tarehe ya kufungua. Mpango unaanza miezi sita kabla ya kufungua hadi mwezi wa kwanza wa biashara, na mtaji wa awali unatolewa sambamba nao.')}
  </div>
  ${fig({title:['How a site is chosen','Jinsi eneo linavyochaguliwa'],sub:['Weights in the location score, out of 100','Uzito katika alama ya eneo, kati ya 100'],src:['Source: section 7.1 location-scoring tool','Chanzo: zana ya kupima eneo sehemu 7.1'],note:['Any criterion scored 1 out of 5 is a deal-breaker, whatever the total','Kigezo chochote chenye alama 1 kati ya 5 ni kizuizi, bila kujali jumla'],
   chart:{type:'parts',parts:[[['Footfall and visibility','Wapita njia na kuonekana'],20,'gold',['the frontage is the main advertisement','mbele ya duka ndilo tangazo kuu']],[['Target households within 3 km','Kaya lengwa ndani ya km 3'],15,'grn',['families, older parents, steady incomes','familia, wazazi wazee, kipato cha uhakika']],[['Rent fits the model','Kodi inaendana na modeli'],15,'grn',['at or under the monthly budget','sawa au chini ya bajeti ya mwezi']],[['Clinics nearby','Kliniki karibu'],10,'grn2',['referrals both ways','rufaa pande zote mbili']],[['Delivery reach','Ufikiaji wa usafirishaji'],10,'grn2',['same day before 15:00','siku hiyohiyo kabla ya saa 9 alasiri']],[['Access and parking','Ufikiaji na maegesho'],10,'grn2',['daladala, BRT, a safe entrance','daladala, BRT, mlango salama']],[['Store-build feasibility','Uwezekano wa kujenga duka'],10,'grn2',['frontage, sign, landlord consent','mbele ya duka, bango, idhini ya mwenye nyumba']],[['Power, water, security','Umeme, maji, ulinzi'],5,'#5b6b64',['backup power, night security','umeme wa akiba, ulinzi wa usiku']],[['Regulatory fit','Uendanaji na kanuni'],5,'#5b6b64',['zoning; a partner pharmacy within reach','mipango miji; famasia mshirika karibu']]]}})}
  <div class="v3b">
  ${sh('The one open funding item','Kipengele kimoja cha ufadhili kilicho wazi')}
  ${P(`Research, travel and setup before launch are estimated at about TSh ${(g.research_setup_costs/1e6).toFixed(1)}M against a Phase 0 budget of TSh ${(g.phase0_budget/1e6).toFixed(2)}M. The ${tm0(c.I.seed.amount)} seed does not cover them, because it is built for the store itself: the build, the lease advance, the stock, the launch, the losses to break-even and a reserve. The gap is stated rather than hidden, and three ways to close it are set out below: add it to the round, have the founders pre-fund it, or run a leaner Phase 0.`,`Utafiti, safari na maandalizi kabla ya uzinduzi vinakadiriwa kuwa takriban TSh milioni ${(g.research_setup_costs/1e6).toFixed(1)} dhidi ya bajeti ya Awamu 0 ya TSh milioni ${(g.phase0_budget/1e6).toFixed(2)}. Mtaji wa awali wa ${tm0(c.I.seed.amount)} haugharamii gharama hizo, kwa sababu umejengwa kwa ajili ya duka lenyewe: ujenzi, malipo ya awali ya kodi, bidhaa, uzinduzi, hasara hadi kutopata hasara na akiba. Pengo linaelezwa wazi badala ya kufichwa, na njia tatu za kulifunga zimeelezwa hapa chini: kuliongeza kwenye awamu, waanzilishi kulilipia mapema, au kuendesha Awamu 0 nyepesi zaidi.`)}
  ${calc({t:['Worked example · the gap against the seed','Mfano wa hesabu · pengo dhidi ya mtaji wa awali'],
   rows:[['Research, travel and setup needed','Utafiti, safari na maandalizi yanayohitajika',`TSh ${(g.research_setup_costs/1e6).toFixed(1)}M`],['− Phase 0 budget in the model','− bajeti ya Awamu 0 katika modeli',`− TSh ${(g.phase0_budget/1e6).toFixed(2)}M`],['Gap','Pengo',`TSh ${(gap/1e6).toFixed(2)}M`],['As a share of the seed','Kama sehemu ya mtaji wa awali',pc(gap/c.I.seed.amount,1),1]],
   n:['To be settled before the term sheet. Adding it to the round at the same pre-money value would raise the investor’s share slightly while keeping the founders above their 25% floor.','Litatatuliwa kabla ya hati ya masharti. Kuliongeza kwenye awamu kwa thamani ileile ya kabla ya uwekezaji kungeongeza kidogo hisa ya mwekezaji huku waanzilishi wakibaki juu ya kiwango chao cha chini cha 25%.']})}
  ${imp('The setup plan is sequenced so that money is never spent ahead of permission: the lease is signed only on a scored site, stock is ordered only once the licences are in hand, and the second tranche of the seed is released only when that has happened. The largest setup risk, a delayed sector permit, therefore costs time rather than stock that cannot be sold.','Mpango wa maandalizi umepangwa ili fedha zisitumike kabla ya ruhusa: mkataba wa pango unasainiwa tu kwa eneo lililopimwa, bidhaa zinaagizwa tu leseni zikiwa mkononi, na awamu ya pili ya mtaji wa awali inatolewa tu hayo yakishatokea. Hatari kubwa zaidi ya maandalizi, kibali cha sekta kuchelewa, kwa hiyo inagharimu muda badala ya bidhaa zisizoweza kuuzwa.')}
  </div>`]];};

/* ================= 7.2 GOVERNANCE ================= */
window.V3MODS['s7-2']=()=>{const c=CUR(),om=Object.values(c.I.opex_month).reduce((a,b)=>a+b,0),sd=c.I.seed;
 return [[['In short · control in proportion to the money','Uchambuzi · udhibiti kulingana na fedha'],`<div class="v3b">
  ${V.optSwitch()}
  ${lede('Governance in a first-store company has one job: let the founders run the business day to day while giving the investor a veto over the decisions that could put its capital at risk. The proposal does this with a four-vote board, a written list of reserved matters and a spending matrix sized against the model’s own running costs.','Utawala katika kampuni ya duka la kwanza una kazi moja: kuwaruhusu waanzilishi kuendesha biashara kila siku huku mwekezaji akipewa kura ya turufu kwa maamuzi yanayoweza kuweka mtaji wake hatarini. Pendekezo linafanya hivyo kwa bodi ya kura nne, orodha iliyoandikwa ya mambo yaliyohifadhiwa na jedwali la matumizi lililopimwa dhidi ya gharama za uendeshaji za modeli yenyewe.')}
  </div>
  ${fig({title:['Four votes, no side can act alone on what matters','Kura nne, hakuna upande unaoweza kuamua peke yake mambo muhimu'],sub:['Proposed board seats and votes; quorum 3, investor director included','Viti vya bodi vinavyopendekezwa na kura; akidi 3, mkurugenzi wa mwekezaji akiwemo'],src:['Source: section 7.2 governance proposal','Chanzo: pendekezo la utawala sehemu 7.2'],note:['Proposal, for legal review under the Companies Act, 2002','Pendekezo, kwa mapitio ya kisheria chini ya Sheria ya Makampuni, 2002'],
   chart:{type:'parts',parts:[[['Founder directors','Wakurugenzi waanzilishi'],2,'grn',['strategy, sourcing, daily running','mkakati, ununuzi, uendeshaji wa kila siku']],[['Investor director','Mkurugenzi wa mwekezaji'],1,'gold',['consent on reserved matters','idhini kwa mambo yaliyohifadhiwa']],[['Independent chair','Mwenyekiti huru'],1,'grn2',['health retail or finance','biashara ya afya au fedha']]]}})}
  <div class="v3b">
  ${calc({t:['Worked example · how the spending limits are sized','Mfano wa hesabu · jinsi mipaka ya matumizi inavyopimwa'],
   rows:[['Running costs a month (model)','Gharama za uendeshaji kwa mwezi (modeli)',tm0(om)],['Store lead approves stock reorders up to','Kiongozi wa duka anaidhinisha kuagiza bidhaa hadi','TSh 1.5M'],['Both founders approve up to','Waanzilishi wote wawili wanaidhinisha hadi','TSh 25M'],['Needs investor consent: borrowing above, any new store (TSh 170M) or any new share','Inahitaji idhini ya mwekezaji: mkopo zaidi ya, duka lolote jipya (TSh milioni 170) au hisa yoyote mpya','TSh 20M',1]],
   n:['Routine spending never waits for a founder or the board; anything that changes ownership, adds debt or opens a store does. The seed tranches are released only against milestones reported in the monthly investor pack.','Matumizi ya kawaida hayasubiri mwanzilishi wala bodi; chochote kinachobadilisha umiliki, kuongeza deni au kufungua duka kinasubiri. Awamu za mtaji wa awali zinatolewa tu dhidi ya hatua zinazoripotiwa katika ripoti ya kila mwezi ya mwekezaji.']})}
  ${P(`Every month, by the 10th, the investor receives a one-page pack generated from the store system: repeat demand (visitors, checks, members, churn), operating simplicity (time to pay, stock-outs, delivery on time) and economics (revenue, gross margin, cash). The same system sends the founders a 21:00 report every evening, so a problem is seen the day it happens rather than at the quarter end. The tranches of the ${tm0(sd.amount)} seed are released only against milestones that this pack reports.`,`Kila mwezi, kufikia tarehe 10, mwekezaji anapokea ripoti ya ukurasa mmoja inayotolewa na mfumo wa duka: mahitaji yanayojirudia (wageni, vipimo, wanachama, wanaoondoka), urahisi wa uendeshaji (muda wa kulipa, bidhaa kukosekana, usafirishaji kwa wakati) na uchumi (mapato, faida ghafi, fedha taslimu). Mfumo huohuo unawatumia waanzilishi ripoti ya saa 3 usiku kila jioni, hivyo tatizo linaonekana siku linapotokea badala ya mwisho wa robo mwaka. Awamu za mtaji wa awali wa ${tm0(sd.amount)} zinatolewa tu dhidi ya hatua ambazo ripoti hii inaonyesha.`)}
  ${imp('The structure is balanced on purpose. The founders cannot outvote the investor on the matters that protect its capital, and the investor cannot run the company from the board. For a development-finance fund, the reporting and the reserved matters are the familiar minimum; for a private investor, they are what makes a minority stake safe to hold.','Muundo huu umesawazishwa kwa makusudi. Waanzilishi hawawezi kumshinda mwekezaji kwa kura kwenye mambo yanayolinda mtaji wake, na mwekezaji hawezi kuendesha kampuni kutoka kwenye bodi. Kwa mfuko wa fedha za maendeleo, ripoti na mambo yaliyohifadhiwa ni kiwango cha chini kinachojulikana; kwa mwekezaji binafsi, ndivyo vinavyofanya hisa ndogo kuwa salama kushikilia.')}
  </div>`]];};

/* ================= 7.4 IMPACT ================= */
window.V3MODS['s7-4']=()=>{const c=CUR(),Y=c.B.years,per=8;
 return [[['In short · measured outputs, not claimed lives','Uchambuzi · matokeo yanayopimwa, si maisha yanayodaiwa'],`<div class="v3b">
  ${lede('Most high blood pressure in Tanzania is hidden: only 17.6% of adults who have it know it, and 2.2% have it under control. Most diabetes is undiagnosed. Treatment fails when supplies run out, and the time spent fetching them falls mostly on women. Afya Basics addresses each of these through what it controls, and reports only what it can count.','Shinikizo la damu nyingi Tanzania limejificha: ni 17.6% tu ya watu wazima walionalo wanaojua, na 2.2% wamelidhibiti. Kisukari kingi hakijagunduliwa. Matibabu yanashindwa mahitaji yanapoisha, na muda unaotumika kuyafuata unawaangukia zaidi wanawake. Afya Basics inashughulikia kila moja kupitia kile inachokidhibiti, na inaripoti tu kile inachoweza kuhesabu.')}
  ${kpis([['14,727','free Afya Checks in year 1 (target)','Afya Check za bure mwaka wa 1 (lengo)'],['~2,209','readings referred to a clinic in year 1','vipimo vilivyopewa rufaa kliniki mwaka wa 1'],[`${nf(Y[11].stores*per)}`,'direct, formal store jobs by year 12','ajira rasmi za moja kwa moja madukani ifikapo mwaka 12',1],['100%','products registered and verified','bidhaa zilizosajiliwa na kuthibitishwa']])}
  </div>
  ${fig({title:['Formal jobs grow store by store','Ajira rasmi zinakua duka kwa duka'],sub:['Direct store jobs at eight per store, all with NSSF contributions','Ajira za moja kwa moja madukani, nane kwa kila duka, zote zikiwa na michango ya NSSF'],src:['Source: master model, stores by year × staff plan','Chanzo: modeli kuu, maduka kwa mwaka × mpango wa wafanyakazi'],note:['Packing hub, head office and supplier jobs come on top and are not counted','Ajira za kituo cha kufungasha, ofisi kuu na wasambazaji ni za ziada na hazihesabiwi'],
   chart:{type:'cols',max:400,ticks:[0,100,200,300,400],bars:Y.map(y=>[[`Y${y.year}`,`M${y.year}`],y.stores*per,nf(y.stores*per),y.year===12?'gold':'grn2'])}})}
  <div class="v3b">
  ${calc({t:['Worked example · from checks to clinic visits','Mfano wa hesabu · kutoka vipimo hadi ziara za kliniki'],
   rows:[['Free Afya Checks in year 1','Afya Check za bure mwaka wa 1','14,727'],['× share above the adviser’s referral threshold','× sehemu iliyo juu ya kiwango cha rufaa cha mshauri','≈ 15%'],['Readings referred to a clinic','Vipimo vilivyopewa rufaa kliniki','≈ 2,209'],['Confirmed clinic visits: at least half, after 14 days','Ziara za kliniki zilizothibitishwa: angalau nusu, baada ya siku 14','≥ 1,100',1]],
   n:['Afya Basics does not diagnose or treat and cannot attribute lives saved. It counts checks, referrals, confirmed visits, members who never ran out in a month, and verified products. Each target is logged by the system and reviewed quarterly.','Afya Basics haitambui magonjwa wala haitibu na haiwezi kudai maisha yaliyookolewa. Inahesabu vipimo, rufaa, ziara zilizothibitishwa, wanachama ambao hawakuishiwa katika mwezi, na bidhaa zilizothibitishwa. Kila lengo linarekodiwa na mfumo na kupitiwa kila robo mwaka.']})}
  ${imp('For a development-finance investor the impact case and the commercial case are the same mechanism. The free check brings people in, the referral protects them, the monthly box keeps treatment going, and each of those steps is also what makes a member stay. The outputs are measurable from day one and align with SDG targets 3.4, 3.8 and 8.5.','Kwa mwekezaji wa fedha za maendeleo, hoja ya athari na hoja ya biashara ni utaratibu mmoja. Kipimo cha bure kinawaleta watu, rufaa inawalinda, boksi la mwezi linaendeleza matibabu, na kila hatua kati ya hizo ndiyo pia inamfanya mwanachama abaki. Matokeo yanapimika tangu siku ya kwanza na yanaendana na malengo ya SDG 3.4, 3.8 na 8.5.')}
  </div>`]];};

/* ================= 7.5 PROOF PACK ================= */
window.V3MODS['s7-5']=()=>[[['In short · what can be checked today, and what cannot yet','Uchambuzi · kinachoweza kuthibitishwa leo, na kisichoweza bado'],`<div class="v3b">
  ${lede('An investor deciding on a first-store company is asked to trust people before there are results. This section replaces as much of that trust as possible with things that can be checked: answers to the hard questions, a data room with the status of every document, the open questions stated openly, and the sources behind every figure in the showroom.','Mwekezaji anayefanya uamuzi kuhusu kampuni ya duka la kwanza anaombwa kuwaamini watu kabla ya kuwepo matokeo. Sehemu hii inabadilisha kiasi kikubwa iwezekanavyo cha imani hiyo kwa mambo yanayoweza kuthibitishwa: majibu ya maswali magumu, chumba cha nyaraka chenye hali ya kila hati, maswali yaliyo wazi yakielezwa waziwazi, na vyanzo nyuma ya kila takwimu katika chumba hiki cha maonyesho.')}
  </div>
  ${fig({title:['The data room: what exists, and when the rest arrives','Chumba cha nyaraka: kilichopo, na lini vingine vitafika'],sub:['24 documents by status','Hati 24 kwa hali yake'],src:['Source: section 7.5 data-room index','Chanzo: orodha ya chumba cha nyaraka sehemu 7.5'],note:['Each line in the index shows its owner and the step at which it is prepared','Kila mstari katika orodha unaonyesha mhusika wake na hatua ambayo utaandaliwa'],
   chart:{type:'parts',parts:[[['Exist today','Zipo leo'],5,'gold',['the model, this showroom, the sources','modeli, chumba hiki cha maonyesho, vyanzo']],[['Prepared before closing','Zinaandaliwa kabla ya kufunga'],13,'grn',['company documents, quotes, lease, agreements','nyaraka za kampuni, nukuu, pango, mikataba']],[['After funding','Baada ya ufadhili'],6,'grn2',['licences and permits that need the store','leseni na vibali vinavyohitaji duka']]]}})}
  <div class="v3b">
  ${kpis([['30','hard investor questions answered with live model numbers','maswali magumu ya wawekezaji yamejibiwa kwa namba hai za modeli'],['14','open questions, each with the step that settles it','maswali yaliyo wazi, kila moja na hatua inayolitatua'],['332','unique sources across the showroom','vyanzo vya kipekee katika chumba chote cha maonyesho'],['1','master model behind every number','modeli kuu moja nyuma ya kila namba',1]])}
  ${P('Several questions are already settled and are marked as such: the seed amount for each store option, VAT treatment, employer on-costs and the decision that Afya sells no medicines. The rest are stated with the step at which they will be closed, from the Phase 0 funding and the founders’ share split to the flagship site and the Kiswahili review. Nothing that affects the investment is left unstated.','Maswali kadhaa tayari yametatuliwa na yamewekwa alama hivyo: kiasi cha mtaji wa awali kwa kila chaguo la duka, utaratibu wa VAT, michango ya mwajiri na uamuzi kwamba Afya haiuzi dawa. Mengine yameelezwa pamoja na hatua ambayo yatafungwa, kuanzia ufadhili wa Awamu 0 na mgawanyo wa hisa za waanzilishi hadi eneo la duka kuu na mapitio ya Kiswahili. Hakuna jambo linaloathiri uwekezaji ambalo halijaelezwa.')}
  ${imp('The proof pack does not ask the investor to accept the plan. It shows where every number comes from, what is still a planning estimate and what must be confirmed before money moves. That is the standard a development-finance fund applies, and it is the standard this showroom has been built to meet.','Kifurushi cha uthibitisho hakimwombi mwekezaji kukubali mpango. Kinaonyesha kila namba inatoka wapi, kipi bado ni makadirio ya mipango na kipi lazima kithibitishwe kabla fedha hazijahamishwa. Hicho ndicho kiwango ambacho mfuko wa fedha za maendeleo unakitumia, na ndicho kiwango ambacho chumba hiki cha maonyesho kimejengwa kukifikia.')}
  </div>`]];
})();

;
/* brief6 · v3 analyst briefs for Part 6 · Money. These follow the funding switch (MODEL.cur). Also: 5.4 lean note, 6.3 comparison module removed. */
(function(){
'use strict';
const V=window.V3;if(!V)return;const {L,P,lede,sh,imp,calc,fig,kpis}=V;
window.V3MODS=window.V3MODS||{};
const nf=n=>Math.round(n).toLocaleString('en'),tm=n=>'TSh '+(n/1e6).toFixed(1)+'M',tm0=n=>'TSh '+Math.round(n/1e6)+'M',pc=(n,d)=>(n*100).toFixed(d||0)+'%';
const CUR=()=>{const M=window.MODEL,lean=!!(M.isLean&&M.isLean());return {M,lean,I:M.cur.inputs,B:M.cur.get('base'),D:M.cur.get('down'),opt:lean?['start-small option','chaguo la kuanza kidogo']:['flagship option','chaguo la duka kuu']}};
const optTag=c=>L(`Shown for the ${c.opt[0]} · ${tm0(c.I.seed.amount)} seed`,`Inaonyeshwa kwa ${c.opt[1]} · mtaji wa awali ${tm0(c.I.seed.amount)}`);

/* ================= 6.1 FINANCIALS ================= */
window.V3MODS['s6-1']=()=>{const c=CUR(),B=c.B,y1=B.y1,m=B.months,x=m[11],be=B.breakeven_month,deep=Math.min(...m.map(q=>q.cum_profit));
 const cogs=x.revenue-x.gross_profit;
 return [[['In short · how the first store turns profitable','Uchambuzi · jinsi duka la kwanza linavyofikia faida'],`<div class="v3b">
  ${V.optSwitch()}
  ${lede(`In its first year the store is building a membership base, so it starts with losses that shrink every month. In the base case of the ${c.opt[0]} it makes its first monthly profit in month ${be}; the deepest point of cumulative losses is ${tm(-deep)}, which the seed is sized to cover with a reserve to spare.`,`Katika mwaka wake wa kwanza duka linajenga wanachama, hivyo linaanza na hasara zinazopungua kila mwezi. Katika hali ya msingi ya ${c.opt[1]} linapata faida ya kwanza ya mwezi katika mwezi wa ${be}; kina cha juu cha hasara zilizojilimbikiza ni ${tm(-deep)}, ambacho mtaji wa awali umepangwa kukigharamia pamoja na akiba.`)}
  ${kpis([[tm0(y1.revenue),'Year-1 revenue, net of VAT','mapato ya Mwaka 1, bila VAT'],['−'+tm0(-y1.profit),'Year-1 result, store level','matokeo ya Mwaka 1, ngazi ya duka'],['Month '+be,'first month with a profit','mwezi wa kwanza wenye faida',1],[tm(-deep),'deepest cumulative loss, covered by the seed','kina cha juu cha hasara, kinagharamiwa na mtaji wa awali',1]])}
  ${sh('Twelve months, one direction','Miezi kumi na miwili, mwelekeo mmoja')}
  ${P('The chart shows the store’s result in each of its first twelve months. Losses shrink steadily as visitors, members and online orders build, while running costs stay almost flat: the business has high fixed costs and rising revenue, so each additional member falls almost entirely to the bottom line once the fixed costs are covered.','Chati inaonyesha matokeo ya duka katika kila moja ya miezi yake kumi na miwili ya kwanza. Hasara zinapungua taratibu kadiri wageni, wanachama na oda za mtandaoni zinavyoongezeka, huku gharama za uendeshaji zikibaki karibu sawa: biashara ina gharama kubwa zisizobadilika na mapato yanayoongezeka, hivyo kila mwanachama wa ziada anaongeza karibu moja kwa moja kwenye faida pindi gharama zisizobadilika zinapolipwa.')}
  </div>
  ${fig({title:[`Monthly result of the first store: profit from month ${be}`,`Matokeo ya kila mwezi ya duka la kwanza: faida kuanzia mwezi ${be}`],sub:['Store-level profit by month, year 1, base case, TSh million','Faida ya ngazi ya duka kwa mwezi, mwaka 1, hali ya msingi, TSh milioni'],src:['Source: master financial model','Chanzo: modeli kuu ya fedha'],note:[`${c.opt[0][0].toUpperCase()+c.opt[0].slice(1)}`,`${c.opt[1][0].toUpperCase()+c.opt[1].slice(1)}`],
   chart:{type:'pn',max:Math.max(6,Math.ceil(Math.max(...m.map(q=>q.profit/1e6))/2)*2+2),min:Math.floor(Math.min(...m.map(q=>q.profit/1e6))/5)*5,ticks:[Math.floor(Math.min(...m.map(q=>q.profit/1e6))/5)*5,0],tf:t=>t,bars:m.map((q,i)=>[['M'+(i+1),'M'+(i+1)],+(q.profit/1e6).toFixed(1),(q.profit/1e6).toFixed(1)])}})}
  <div class="v3b">
  ${sh('Month 12, from revenue to profit','Mwezi 12, kutoka mapato hadi faida')}
  ${P('The bridge takes one month at the end of year 1 and follows every shilling from revenue to profit. It shows the two numbers that decide the business: a gross margin of just over a quarter of revenue, and a fixed cost base that has to be covered before any profit appears.','Daraja linachukua mwezi mmoja mwishoni mwa mwaka 1 na kufuata kila shilingi kutoka mapato hadi faida. Linaonyesha namba mbili zinazoamua biashara: faida ghafi ya zaidi kidogo ya robo ya mapato, na gharama zisizobadilika zinazopaswa kulipwa kabla faida yoyote haijaonekana.')}
  </div>
  ${fig({style:'navy',title:[`Month 12: ${tm(x.revenue)} of revenue, ${tm(x.profit)} of profit`,`Mwezi 12: mapato ${tm(x.revenue)}, faida ${tm(x.profit)}`],sub:['One month, base case, TSh million','Mwezi mmoja, hali ya msingi, TSh milioni'],src:['Source: master financial model','Chanzo: modeli kuu ya fedha'],note:[`Gross margin ${pc(x.gross_profit/x.revenue)}`,`Faida ghafi ${pc(x.gross_profit/x.revenue)}`],
   chart:{type:'bridge',max:Math.ceil(x.revenue/1e6/10)*10,fmt:v=>v.toFixed(1),steps:[[['Revenue','Mapato'],+(x.revenue/1e6).toFixed(1),'t'],[['Cost of goods,|services and fees','Gharama za bidhaa,|huduma na ada'],-+(cogs/1e6).toFixed(1)],[['Gross|profit','Faida|ghafi'],+(x.gross_profit/1e6).toFixed(1),'t'],[['Running|costs','Gharama za|uendeshaji'],-+(x.opex/1e6).toFixed(1)],[['Profit','Faida'],+(x.profit/1e6).toFixed(1),'t']]}})}
  <div class="v3b">
  ${calc({t:['Worked example · what one more member is worth after break-even','Mfano wa hesabu · thamani ya mwanachama mmoja zaidi baada ya kufikia faida'],p:['Once running costs are covered, each extra member adds their box margin almost directly to profit, because rent, staff and systems do not rise with one more box.','Pindi gharama za uendeshaji zinapolipwa, kila mwanachama wa ziada anaongeza faida ya boksi lake karibu moja kwa moja kwenye faida, kwa sababu kodi, wafanyakazi na mifumo haviongezeki kwa boksi moja zaidi.'],
   rows:[['Earnings per member a month (section 3.4)','Mapato kwa mwanachama kwa mwezi (sehemu 3.4)','TSh 20,454'],['× 100 extra members','× wanachama 100 wa ziada','TSh 2,045,400'],['× 12 months','× miezi 12','TSh 24.5M',1]],
   n:['This operating leverage is why the plan concentrates on membership in year 1: the same store, with the same team, becomes markedly more profitable as the member base grows.','Nguvu hii ya uendeshaji ndiyo sababu mpango unazingatia uanachama katika mwaka 1: duka lilelile, na timu ileile, linakuwa na faida kubwa zaidi kadiri idadi ya wanachama inavyoongezeka.']})}
  ${imp(`The financial case for the first store rests on two observable things: members joining at the planned rate, and the gross margin holding at just over a quarter of revenue. Both are reported monthly, and both are tested before any growth capital is raised. In the downside case ${c.D.breakeven_month?'the store reaches its first monthly profit in month '+c.D.breakeven_month:'the store does not reach a monthly profit in year 1'}, which is why the seed includes a working-capital reserve.`,`Hoja ya kifedha ya duka la kwanza inategemea mambo mawili yanayoonekana: wanachama kujiunga kwa kiwango kilichopangwa, na faida ghafi kubaki zaidi kidogo ya robo ya mapato. Yote mawili yanaripotiwa kila mwezi, na yote yanapimwa kabla mtaji wowote wa ukuaji haujatafutwa. Katika hali mbaya ${c.D.breakeven_month?'duka linapata faida ya kwanza ya mwezi katika mwezi wa '+c.D.breakeven_month:'duka halipati faida ya mwezi katika mwaka 1'}, ndiyo maana mtaji wa awali unajumuisha akiba ya mtaji wa kazi.`)}
  </div>`]];};

/* ================= 6.2 CUSTOMER-FUNDED MODEL ================= */
window.V3MODS['s6-2']=()=>{const c=CUR(),I=c.I,o=I.opex_month,tot=Object.values(o).reduce((a,b)=>a+b,0),O=I.online;
 return [[['In short · the customer pays for the running of the store','Uchambuzi · mteja analipia uendeshaji wa duka'],`<div class="v3b">
  ${V.optSwitch()}
  ${lede('One rule governs the whole financial design: every recurring cost is recovered inside a price the customer chooses to pay. Investor money builds the store and carries it to break-even; it does not subsidise deliveries, advice or packaging once the store is running.','Kanuni moja inaongoza muundo mzima wa kifedha: kila gharama inayojirudia inarudishwa ndani ya bei ambayo mteja anachagua kulipa. Fedha za mwekezaji zinajenga duka na kulibeba hadi kufikia faida; hazitoi ruzuku kwa usafirishaji, ushauri au vifungashio pindi duka linapofanya kazi.')}
  ${sh('Where the monthly running costs go','Gharama za uendeshaji za kila mwezi zinakwenda wapi')}
  </div>
  ${fig({title:[`${tm(tot)} a month of running costs, by line`,`Gharama za uendeshaji ${tm(tot)} kwa mwezi, kwa mstari`],sub:['Monthly running costs of the first store, master model','Gharama za uendeshaji za kila mwezi za duka la kwanza, modeli kuu'],src:['Source: master model, opex lines','Chanzo: modeli kuu, mistari ya gharama za uendeshaji'],note:[optTag(c),optTag(c)],
   chart:{type:'parts',parts:[[['Rent','Kodi'],Math.round(o.rent/1e3),'gold',['carried by store, box and online sales','inabebwa na mauzo ya duka, boksi na mtandaoni']],[['Staff','Wafanyakazi'],Math.round(o.staff/1e3),'grn',['recovered in the product margin','inarudishwa katika faida ya bidhaa']],[['Marketing','Matangazo'],Math.round(o.marketing/1e3),'grn2',['recovered in the product margin','inarudishwa katika faida ya bidhaa']],[['Everything else','Mengineyo'],Math.round((tot-o.rent-o.staff-o.marketing)/1e3),'#5b6b64',['utilities, systems, check station, insurance, packaging','huduma, mifumo, kituo cha vipimo, bima, vifungashio']]]}})}
  <div class="v3b">
  ${P('Each cost line has a matching source of revenue. Delivery is recovered through the online delivery fee and the packing-and-delivery line inside every box price. Advice and the free check are paid for by the margin on the products customers buy. Premium service is paid for by the Royal card fee. Rent is carried jointly by walk-in sales, boxes and online orders, all of which are served from the same floor.','Kila mstari wa gharama una chanzo chake cha mapato. Usafirishaji unarudishwa kupitia ada ya usafirishaji wa mtandaoni na mstari wa kufungasha na kusafirisha ndani ya bei ya kila boksi. Ushauri na kipimo cha bure vinalipiwa na faida ya bidhaa wanazonunua wateja. Huduma ya hadhi ya juu inalipiwa na ada ya kadi ya Royal. Kodi inabebwa kwa pamoja na mauzo ya dukani, maboksi na oda za mtandaoni, vyote vikihudumiwa kutoka sakafu ileile.')}
  ${calc({t:['Worked example · delivery is paid for twice over','Mfano wa hesabu · usafirishaji unalipiwa zaidi ya gharama yake'],
   rows:[['Online delivery fee, paid by the customer','Ada ya usafirishaji mtandaoni, inayolipwa na mteja','TSh '+nf(O.delivery_fee)],['Rider cost per order in the model','Gharama ya msafirishaji kwa oda katika modeli','− TSh '+nf(O.rider_cost_per_order)],['Margin per online delivery','Faida kwa kila usafirishaji wa mtandaoni','TSh '+nf(O.delivery_fee-O.rider_cost_per_order)],['Packing and delivery inside every box price','Kufungasha na kusafirisha ndani ya bei ya kila boksi','TSh '+nf(I.members.packing_delivery_in_price)],['Recovered cost of delivery','Gharama ya usafirishaji inayorudishwa','100%',1]],
   n:['Planning estimates from the master model. Section 4.3 shows the real cost per drop falling below the budget as routes fill.','Makisio ya mpango kutoka modeli kuu. Sehemu 4.3 inaonyesha gharama halisi kwa kila safari ikishuka chini ya bajeti kadiri njia zinavyojaa.']})}
  ${imp('Because the customer pays for the running of the business, investor capital is used once, for assets and for the climb to break-even, and is not consumed again by growth in volume. Each additional customer therefore improves the economics rather than adding to the cost base, which is the property that makes the model safe to repeat store by store.','Kwa sababu mteja analipia uendeshaji wa biashara, mtaji wa mwekezaji unatumika mara moja, kwa rasilimali na kwa safari ya kufikia faida, na haumalizwi tena na ongezeko la wingi wa mauzo. Kwa hiyo kila mteja wa ziada anaboresha uchumi wa biashara badala ya kuongeza gharama, sifa inayofanya mfumo kuwa salama kurudiwa duka kwa duka.')}
  </div>`]];};

/* ================= 6.3 FUNDING AND USE OF FUNDS ================= */
const SWU={'Launch compliance fees: licences, registrations, first shipment certificate':'Ada za uzingatiaji wa sheria za uzinduzi: leseni, usajili, cheti cha mzigo wa kwanza','Store fit-out & signage':'Ujenzi wa ndani wa duka na alama','Store fit-out & signage (100 m²)':'Ujenzi wa ndani na alama (m² 100)','Lease advance · first 6 months (rent paid up front)':'Kodi ya mapema · miezi 6','Opening stock (about 520 product families)':'Bidhaa za kuanzia (familia 520)','Opening stock (core 300 product families)':'Bidhaa za kuanzia (familia 300)','Technology, Afya Check kiosk & screens':'Teknolojia, kibanda na skrini','Technology: POS, app, manual check corner':'Teknolojia na kona ya kupima','Two electric delivery motorbikes':'Pikipiki mbili za umeme','Launch marketing':'Matangazo ya uzinduzi','Pre-opening team: hiring & training':'Timu kabla ya kufungua','Operating losses & lease advances until break-even (month 11)':'Hasara hadi kufikia faida','Operating losses & lease advances until break-even':'Hasara hadi kufikia faida','Working-capital reserve · 3 months of running costs excluding rent':'Akiba ya mtaji wa kazi'};
const SHORT={'Launch compliance fees: licences, registrations, first shipment certificate':'Launch compliance','Store fit-out & signage':'Fit-out & signage','Store fit-out & signage (100 m²)':'Fit-out & signage','Lease advance · first 6 months (rent paid up front)':'Lease advance, 6 months','Opening stock (about 520 product families)':'Opening stock','Opening stock (core 300 product families)':'Opening stock','Technology, Afya Check kiosk & screens':'Technology & kiosk','Technology: POS, app, manual check corner':'Technology','Two electric delivery motorbikes':'E-motorbikes','Launch marketing':'Launch marketing','Pre-opening team: hiring & training':'Pre-opening team','Operating losses & lease advances until break-even (month 11)':'Losses to break-even','Operating losses & lease advances until break-even':'Losses to break-even','Working-capital reserve · 3 months of running costs excluding rent':'Working-capital reserve'};
window.V3MODS['s6-3']=()=>{const c=CUR(),sd=c.I.seed,tr=sd.tranches;
 const ms=[['On signing: lease advance, company and licences, fit-out starts','Wakati wa kusaini: kodi ya mapema, kampuni na leseni, ujenzi unaanza'],['Fit-out complete, TMDA and business licences in hand, stock ordered','Ujenzi umekamilika, leseni za TMDA na biashara zipo, bidhaa zimeagizwa'],['Store open three months, 100 Afya Box members, monthly loss below target','Duka limefunguliwa miezi mitatu, wanachama 100 wa Afya Box, hasara ya mwezi chini ya lengo']];
 return [[['In short · what the seed buys, and when it is released','Uchambuzi · mtaji wa awali unanunua nini, na unatolewa lini'],`<div class="v3b">
  ${V.optSwitch()}
  ${lede(`The ${c.opt[0]} asks for ${tm0(sd.amount)}. Every shilling is allocated to a named line, and the money is released in three tranches, each only when a milestone an investor can verify has been met. The investor is never more than one milestone ahead of the evidence.`,`${c.opt[1][0].toUpperCase()+c.opt[1].slice(1)} linaomba ${tm0(sd.amount)}. Kila shilingi imepangiwa mstari wenye jina, na fedha zinatolewa kwa awamu tatu, kila moja pale tu hatua ambayo mwekezaji anaweza kuithibitisha imefikiwa. Mwekezaji hayuko kamwe zaidi ya hatua moja mbele ya ushahidi.`)}
  </div>
  ${fig({title:[`The ${tm0(sd.amount)} seed, by use`,`Mtaji wa awali wa ${tm0(sd.amount)}, kwa matumizi`],sub:['Use of funds, TSh million. Rectangle area is proportional to amount','Matumizi ya fedha, TSh milioni. Eneo la mstatili linalingana na kiasi'],src:['Source: master model, seed use of funds','Chanzo: modeli kuu, matumizi ya mtaji wa awali'],note:[optTag(c),optTag(c)],
   chart:{type:'treemap',unit:'M',fmt:v=>Math.round(v),items:sd.use.map((u,i)=>[[SHORT[u[0]]||u[0],SWU[u[0]]||u[0]],u[1]/1e6,/losses/i.test(u[0])?'gold':/reserve/i.test(u[0])?'#7f9a8d':/Lease/i.test(u[0])?'grn':'grn2'])}})}
  <div class="v3b">
  ${sh('Three tranches, three milestones','Awamu tatu, hatua tatu')}
  </div>
  ${fig({style:'navy',title:['Money follows evidence','Fedha zinafuata ushahidi'],sub:['Seed tranches and the milestone that releases each one','Awamu za mtaji wa awali na hatua inayotoa kila moja'],src:['Source: master model, seed milestones; to be written into the investment agreement','Chanzo: modeli kuu, hatua za mtaji wa awali; zitaandikwa katika mkataba wa uwekezaji'],
   chart:{type:'parts',parts:tr.map((t,i)=>[[`Tranche ${i+1} · ${tm0(sd.amount*t)}`,`Awamu ${i+1} · ${tm0(sd.amount*t)}`],Math.round(t*100),['gold','grn','grn2'][i],ms[i]])}})}
  <div class="v3b">
  ${calc({t:['Worked example · how much of the seed is at risk at each step','Mfano wa hesabu · kiasi gani cha mtaji wa awali kiko hatarini katika kila hatua'],
   rows:[['Released on signing (tranche 1)','Kinachotolewa wakati wa kusaini (awamu 1)',tm0(sd.amount*tr[0])],['Released when the store is built and licensed (tranche 2)','Kinachotolewa duka likijengwa na kupata leseni (awamu 2)',tm0(sd.amount*tr[1])],['Released after three months of trading at target (tranche 3)','Kinachotolewa baada ya miezi mitatu ya biashara kwa lengo (awamu 3)',tm0(sd.amount*tr[2])],['Maximum committed before the store has traded','Kiwango cha juu kinachotolewa kabla duka halijafanya biashara',tm0(sd.amount*(tr[0]+tr[1])),1]],
   n:['If the store misses the third milestone, the last quarter of the seed is not released until the founders and the investor agree a revised plan. Milestones are a proposal, to be settled in the investment agreement after legal review.','Kama duka litakosa hatua ya tatu, robo ya mwisho ya mtaji wa awali haitolewi hadi waanzilishi na mwekezaji wakubaliane mpango uliorekebishwa. Hatua ni pendekezo, litakalokamilishwa katika mkataba wa uwekezaji baada ya ukaguzi wa kisheria.']})}
  ${(()=>{const Y=c.B.years;let cum=0,mn=0,mnY=2,peak=null;const rows=Y.slice(1).map(y=>{const cf=y.ebitda-y.capex;cum+=cf;if(cum<mn){mn=cum;mnY=y.year}return [y.year,y.stores,cf,cum]});const need=-mn,bn=v=>'TSh '+(v/1e9).toFixed(2)+'B',bnS=v=>'TSh bilioni '+(v/1e9).toFixed(2);const back=(rows.find(r=>r[3]>=0)||[null])[0];
   return `${sh('What the seed does not pay for: the chain','Kile ambacho mtaji wa awali haugharamii: mtandao wa maduka')}
  ${P(`The seed builds one store and carries it to break-even. It does not fund the chain. The twelve-year plan grows from 1 store to ${Y[Y.length-1].stores}, and each new store costs about ${tm0(c.I.growth.new_store_capex)} to build before it earns. From year 2, the cash the stores generate, less the cost of opening new ones, stays below zero until year ${mnY}; at its deepest the plan needs about <strong>${bn(need)} of outside capital beyond the seed</strong>. That money is not part of this round. It would be raised in later rounds, or partly as debt, only once store one has proved its numbers, and each later round dilutes every shareholder, the seed investor included.`,`Mtaji wa awali unajenga duka moja na kulifikisha kwenye kiwango cha kutopata hasara. Haugharamii mtandao wa maduka. Mpango wa miaka kumi na miwili unakua kutoka duka 1 hadi ${Y[Y.length-1].stores}, na kila duka jipya linagharimu takriban ${tm0(c.I.growth.new_store_capex)} kujenga kabla halijaanza kuingiza. Kuanzia mwaka wa 2, fedha zinazozalishwa na maduka, ukitoa gharama ya kufungua mapya, zinabaki chini ya sifuri hadi mwaka wa ${mnY}; katika kina chake mpango unahitaji takriban <strong>${bnS(need)} za mtaji wa nje zaidi ya mtaji wa awali</strong>. Fedha hizo si sehemu ya awamu hii. Zingetafutwa katika awamu za baadaye, au sehemu kama mkopo, pale tu duka la kwanza litakapothibitisha namba zake, na kila awamu ya baadaye inapunguza hisa za kila mwenyehisa, akiwemo mwekezaji wa awali.`)}
  </div>
  ${fig({title:[`About ${bn(need)} of growth capital is needed after the seed`,`Takriban ${bnS(need)} za mtaji wa ukuaji zinahitajika baada ya mtaji wa awali`],sub:['Cumulative cash from stores less new-store build cost, from year 2, base case, TSh million','Fedha za jumla kutoka madukani ukitoa gharama ya kujenga maduka mapya, kuanzia mwaka 2, hali ya msingi, TSh milioni'],src:['Source: master model, twelve-year table (EBITDA less new-store capital spend)','Chanzo: modeli kuu, jedwali la miaka kumi na miwili (EBITDA ukitoa matumizi ya mtaji ya maduka mapya)'],note:['Before tax, interest and working capital for new stores; a planning estimate, not a funding commitment','Kabla ya kodi, riba na mtaji wa kazi wa maduka mapya; makadirio ya mipango, si ahadi ya ufadhili'],
   chart:{type:'cols',twoLine:1,max:Math.ceil(need/5e8)*500,ticks:Array.from({length:Math.ceil(need/5e8)+1},(_,i)=>i*500),hl:rows.findIndex(r=>r[0]===mnY),bars:rows.filter(r=>r[3]<0).map(r=>[[`Y${r[0]}|${r[1]} stores`,`M${r[0]}|maduka ${r[1]}`],Math.round(-r[3]/1e6),nf(-r[3]/1e6),r[0]===mnY?'gold':'grn2'])}})}
  <div class="v3b">
  ${calc({t:['Worked example · how the outside capital is counted','Mfano wa hesabu · jinsi mtaji wa nje unavyohesabiwa'],
   rows:rows.filter(r=>r[0]<=mnY).map(r=>[`Year ${r[0]}: ${r[1]} stores, cash after new-store spend`,`Mwaka ${r[0]}: maduka ${r[1]}, fedha baada ya matumizi ya maduka mapya`,(r[2]<0?'− ':'+ ')+tm0(Math.abs(r[2]))]).concat([['Deepest cumulative need, before the chain pays for itself','Hitaji kubwa zaidi la jumla, kabla mtandao haujajilipia',bn(need),1]]),
   n:[`Year 1 is left out because the seed covers store one’s build and its losses to break-even. ${back?`The cumulative line turns positive in year ${back}.`:''} The figure falls if stores open more slowly, which is why growth is gated on store one’s results.`,`Mwaka wa 1 umeachwa kwa sababu mtaji wa awali unagharamia ujenzi wa duka la kwanza na hasara zake hadi kutopata hasara. ${back?`Mstari wa jumla unakuwa chanya mwaka wa ${back}.`:''} Kiasi hiki kinapungua maduka yakifunguliwa polepole zaidi, ndiyo maana ukuaji unategemea matokeo ya duka la kwanza.`]})}`})()}
  ${imp('The structure limits the investor’s exposure at every stage: most of the money is committed only after the store exists and is licensed, and the final tranche only after it has traded at target. Together with the working-capital reserve, it means the seed is designed to reach break-even with room for the downside case, not to depend on everything going right.','Muundo huu unapunguza hatari ya mwekezaji katika kila hatua: sehemu kubwa ya fedha inatolewa tu baada ya duka kuwepo na kupata leseni, na awamu ya mwisho tu baada ya kufanya biashara kwa lengo. Pamoja na akiba ya mtaji wa kazi, inamaanisha mtaji wa awali umeundwa kufikia faida ukiwa na nafasi ya hali mbaya, si kutegemea kila kitu kwenda sawa.')}
  </div>`]];};

/* ================= 6.4 OWNERSHIP ================= */
window.V3MODS['s6-4']=()=>{const c=CUR(),O=c.I.ownership,sd=c.I.seed,post=sd.amount/O.seed_investor_share,pre=post-sd.amount;
 return [[['In short · shared upside, protected founders','Uchambuzi · faida ya pamoja, waanzilishi wanalindwa'],`<div class="v3b">
  ${V.optSwitch()}
  ${lede(`For a seed of ${tm0(sd.amount)} the seed investor would own ${pc(O.seed_investor_share)} of the company, the founders ${pc(O.founders_after_seed)} and an option pool for key staff ${pc(O.option_pool)}. Through later rounds the founders intend to keep at least ${pc(O.founders_floor)}, so that the people running the business stay committed to it.`,`Kwa mtaji wa awali wa ${tm0(sd.amount)} mwekezaji wa awali angemiliki ${pc(O.seed_investor_share)} ya kampuni, waanzilishi ${pc(O.founders_after_seed)} na hisa za wafanyakazi muhimu ${pc(O.option_pool)}. Katika awamu zinazofuata waanzilishi wanakusudia kubaki na angalau ${pc(O.founders_floor)}, ili watu wanaoendesha biashara waendelee kujitolea kwayo.`)}
  </div>
  ${fig({title:['The company after the seed round','Kampuni baada ya awamu ya mtaji wa awali'],sub:['Illustrative cap table, % of shares','Mgawanyo wa hisa wa mfano, % ya hisa'],src:['Source: master model, ownership inputs · illustrative, legal review needed','Chanzo: modeli kuu, pembejeo za umiliki · mfano, ukaguzi wa kisheria unahitajika'],note:[optTag(c),optTag(c)],
   chart:{type:'parts',parts:[[['Founders','Waanzilishi'],Math.round(O.founders_after_seed*100),'grn',['run the business; floor of '+pc(O.founders_floor)+' through later rounds','wanaendesha biashara; kiwango cha chini '+pc(O.founders_floor)]],[['Seed investor','Mwekezaji wa awali'],Math.round(O.seed_investor_share*100),'gold',['for '+tm0(sd.amount),'kwa '+tm0(sd.amount)]],[['Option pool','Hisa za wafanyakazi'],Math.round(O.option_pool*100),'#7f9a8d',['to recruit and keep key staff','kuajiri na kubakiza wafanyakazi muhimu']]]}})}
  <div class="v3b">
  ${calc({t:['Worked example · the valuation implied by the terms','Mfano wa hesabu · thamani inayotokana na masharti'],
   rows:[['Seed amount','Mtaji wa awali',tm0(sd.amount)],['÷ share for the seed investor','÷ hisa za mwekezaji wa awali',pc(O.seed_investor_share)],['Implied post-money value','Thamani baada ya uwekezaji',tm0(post)],['Implied pre-money value (post-money − seed)','Thamani kabla ya uwekezaji (baada − mtaji)',tm0(pre),1]],
   n:['Illustrative only: the share and the valuation are proposals for negotiation, to be confirmed with a lawyer and in the shareholders’ agreement. The sale calculator in this section shows what the stake could be worth under different exit assumptions.','Ni mfano tu: hisa na thamani ni mapendekezo ya majadiliano, yatakayothibitishwa na mwanasheria na katika mkataba wa wanahisa. Kikokotoo cha mauzo katika sehemu hii kinaonyesha thamani ya hisa chini ya makisio tofauti ya kuuza.']})}
  ${imp('The terms align both sides. The investor receives a significant minority stake, information rights and a board seat; the founders keep control of day-to-day decisions and a protected floor that keeps them committed through later rounds. A founder team that cannot be diluted below a quarter is a team that will still be running the business when it is worth selling.','Masharti haya yanaoanisha pande zote mbili. Mwekezaji anapata hisa kubwa za wachache, haki ya kupata taarifa na kiti katika bodi; waanzilishi wanabaki na udhibiti wa maamuzi ya kila siku na kiwango cha chini kilicholindwa kinachowafanya waendelee kujitolea katika awamu zinazofuata. Timu ya waanzilishi isiyoweza kupunguzwa chini ya robo ni timu ambayo bado itakuwa ikiendesha biashara itakapokuwa na thamani ya kuuzwa.')}
  </div>`]];};

window.V3DROP=Object.assign(window.V3DROP||{},{'s6-3':['Two ways to start · TSh 150M or TSh 340M']});
})();
